# Of a repo's calls 0.5.0 stored as kind 'external', how many does a
# dependency index confirm: the name/arity is exported, or generated by a
# `__using__`, by a dependency module the repo imports or uses somewhere.
import json, os, re, sqlite3, subprocess, sys, collections
repo, idx_file, db_file = sys.argv[1:4]
idx = json.load(open(idx_file))
src = subprocess.run(['git', '-C', os.path.expanduser('~/github/' + repo), 'grep', '-hoE', r'^\s*(import|use) [A-Z][A-Za-z0-9_.]*', 'origin/main', '--', '*.ex', '*.exs'], capture_output=True, text=True).stdout
scoped = {l.split()[-1] for l in src.splitlines()}
deps_in_scope = [m for m in scoped if m in idx]
have = collections.defaultdict(list)
for m in deps_in_scope:
    for n, lo, hi in idx[m]['exports'] + idx[m]['using']:
        have[n].append((lo, hi))
db = sqlite3.connect('file:' + db_file + '?mode=ro', uri=True)
S = db.execute("select f.snapshot_id from files f join snapshots s on s.id=f.snapshot_id where f.repo=? order by s.created_at desc limit 1", (repo,)).fetchone()[0]
rows = db.execute("select target from calls where snapshot_id=? and repo=? and kind='external'", (S, repo)).fetchall()
ok = miss = 0; misses = collections.Counter()
for (t,) in rows:
    head, ar = t.rsplit('/', 1); ar = int(ar)
    name = head.rsplit('.', 1)[-1]
    if any(lo <= ar <= hi for lo, hi in have.get(name, [])): ok += 1
    else: miss += 1; misses[t] += 1
print(f"{repo}: {len(rows)} external-kind rows; confirmed {ok}; not confirmed {miss}; dep modules in scope {len(deps_in_scope)}")
for t, n in misses.most_common(15): print(f"  {n:5d} {t}")

# Causes of the unconfirmed, for the plan.
api = {n for n, lo, hi in idx.get('Ecto.Query.API', {}).get('exports', [])}
stdlib_mods = ['ExUnit.Assertions', 'ExUnit.Callbacks', 'ExUnit.Case', 'Kernel', 'Bitwise', 'Logger']
cause = collections.Counter()
for t, n in misses.items():
    head = t.rsplit('/', 1)[0]
    mod, name = (head.rsplit('.', 1) if '.' in head else ('', head))
    if mod.endswith('.Repo') or mod.endswith('Repo'): cause['generated by a library before_compile/adapter (Repo.query!)'] += n
    elif name in api: cause['Ecto query DSL inside from/where (Ecto.Query.API)'] += n
    elif name in ('assert', 'refute', 'assert_raise', 'assert_receive', 'refute_receive', 'setup', 'describe', 'test', 'on_exit', 'start_supervised', 'start_supervised!'): cause['Elixir stdlib (ExUnit), not a Hex package'] += n
    else: cause['other'] += n
for c, n in cause.most_common(): print(f"  {n:5d} {c}")
oth = collections.Counter({t: n for t, n in misses.items()})
